OUT=Path(__file__).resolve().parent/"coupon_inputs"
OUT.mkdir(exist_ok=True)
def deck(material,n,path,mu):
    L=.1
    def nid(i,j,k):return 1+i+(n+1)*(j+(n+1)*k)
    nodes=[(nid(i,j,k),L*i/n,L*j/n,L*k/n) for k,j,i in product(range(n+1),repeat=3)]
    elems=[]
    for k,j,i in product(range(n),repeat=3):
        elems.append((len(elems)+1,nid(i,j,k),nid(i+1,j,k),nid(i+1,j+1,k),nid(i,j+1,k),nid(i,j,k+1),nid(i+1,j,k+1),nid(i+1,j+1,k+1),nid(i,j+1,k+1)))
    s=["*Heading","** REV22 independent material coupon; SI; NOT_RUN","*Node"]
    s+= [", ".join(map(str,v)) for v in nodes]
    s+=["*Element, type=C3D8R, elset=ALL"]+[", ".join(map(str,v)) for v in elems]
    for name,ids in [("BOTTOM",[nid(i,j,0) for i,j in product(range(n+1),repeat=2)]),("TOP",[nid(i,j,n) for i,j in product(range(n+1),repeat=2)]),("PIN",[nid(0,0,0)]),("GUIDE",[nid(n,0,0)])]:
        s+=["*Nset, nset="+name]+[", ".join(map(str,ids[i:i+16])) for i in range(0,len(ids),16)]
    mat=MATERIALS[material].replace("1e-05",str(mu))
    s+=["*Solid Section, elset=ALL, material="+material,",",mat,"*Boundary","BOTTOM, 3, 3","PIN, 1, 2","GUIDE, 2, 2"]
    if path=="tension": points=[(0,0),(1,.0001)]
    elif path=="compression":points=[(0,0),(1,-.0006)]
    else:points=[(0,0),(.1,.000012),(.2,0),(.3,-.00018),(.4,0),(.5,.00003),(.6,0),(.7,-.00035),(.8,0),(.9,.00008),(1,0)]
    s+=["*Amplitude, name=AXIAL"]+[f"{t}, {u}" for t,u in points]
    s+=["*Step, name=COUPON, nlgeom=NO, inc=20000","*Static","0.001, 1., 1.e-10, 0.005","*Boundary, amplitude=AXIAL","TOP, 3, 3, 1.","*Output, field, frequency=1","*Node Output","U, RF","*Element Output","S, E, DAMAGEC, DAMAGET, PEEQ, PEEQT","*Output, history, frequency=1","*Energy Output","ALLIE, ALLWK, ALLVD, ALLDMD, ALLAE","*End Step"]
    return "\n".join(s)+"\n",len(nodes),len(elems)
records=[]
for m in MATERIALS:
    cases=[(n,p,1e-5) for n in (1,2,4) for p in ("tension","compression","cyclic")]
    cases += [(1,p,v) for p in ("tension","compression","cyclic") for v in (0.,1e-6,1e-4)]
    for n,p,v in cases:
        text,nn,ne=deck(m,n,p,v)
        name=f"{m}_{p}_n{n}_mu{v:g}.inp"
        b=text.encode("ascii"); (OUT/name).write_bytes(b)
        records.append(dict(file=name,material=m,mesh_m=.1/n,viscosity_s=v,path=p,nodes=nn,elements=ne,sha256=hashlib.sha256(b).hexdigest(),native="NOT_RUN"))
(OUT/"manifest.json").write_text(json.dumps(records,indent=2))
print("Generated",len(records),"independent inputs; no solver run")
